import http from "node:http";

// Generated by the pinned SvelteKit production adapter.
const { handler } = await import("./build/handler.js");
const version = (
  await Bun.file(
    new URL("./node_modules/@sveltejs/kit/package.json", import.meta.url),
  ).json()
).version;
if (Bun.version !== "1.4.2" || process.env.NODE_ENV !== "production")
  throw new Error("Pinned production Bun required");
http
  .createServer((request, response) => {
    if (request.url === "/health" || request.url === "/metrics") {
      const usage = process.cpuUsage();
      response.writeHead(200, {
        "content-type": "application/json",
        "cache-control": "no-store",
      });
      response.end(
        JSON.stringify(
          request.url === "/health"
            ? {
                status: "ok",
                engine: "sveltekit",
                framework: `SvelteKit ${version}`,
                runtime: `Bun ${Bun.version}`,
                nodeEnv: process.env.NODE_ENV,
              }
            : { cpuTimeMicros: usage.user + usage.system },
        ),
      );
    } else handler(request, response);
  })
  .listen(Number(process.env.PORT), "127.0.0.1");
